home_files.bin/qpdf:
#!/bin/sh
# Stand-in for qpdf: validates anything, copies the first input to the output.
if [ "$1" = "--check" ]; then exit 0; fi
case "$*" in
*" -- "*) eval "out=\${$#}" ;;
*) out="$2" ;;
esac
cp "$1" "$out"

